/**
 * heic-normalize: decode an iPhone HEIC/HEIF file to a standard JPEG/PNG File
 * at the upload boundary, so the rest of your pipeline never sees HEIC.
 *
 * Why: browsers cannot decode HEVC-coded HEIC except Safari 17+, and most web
 * pipelines decode via <img>/createImageBitmap/canvas — none of which has an
 * HEVC decoder outside Safari. HEIC has been the iPhone camera default since
 * iOS 11, so any consumer upload surface receives it constantly.
 *
 * Strategy: non-HEIC passes through untouched (cheap magic-byte check, no
 * decode). HEIC is decoded to a raster — Safari: native createImageBitmap,
 * zero WASM; Chrome/Firefox/Edge: lazy `heic-to` WASM (~1.2 MB, loaded on the
 * first HEIC only) — and re-encoded to JPEG (default) or PNG.
 *
 * Constraints: full-resolution decode — a 48 MP HEIC peaks at several hundred
 * MB of RAM; apply your own megapixel cap downstream. Decode/encode failures
 * throw HeicDecodeError for the caller to surface. Browser-only (needs File,
 * canvas); safe to import in SSR — it only touches browser APIs when called.
 */
/** Re-encode quality for the JPEG normalization target (0..1). 0.92 is a
 *  near-lossless intermediate before whatever processing runs downstream. */
const JPEG_QUALITY = 0.92;
/** Thrown when a HEIC file is recognized but cannot be decoded (no native
 *  support AND the WASM decoder failed — e.g. OOM on a 48 MP photo, or a
 *  truncated/corrupt HEIC). The caller surfaces a user-facing message. */
export class HeicDecodeError extends Error {
    reason;
    constructor(reason, cause) {
        super(reason);
        this.reason = reason;
        this.name = "HeicDecodeError";
        if (cause !== undefined)
            this.cause = cause;
    }
}
/** ISO-BMFF ftyp brands that mean HEIC/HEIF. AVIF shares the ftyp box shape
 *  but every modern browser already decodes it, so it is deliberately NOT
 *  matched here. */
const HEIC_BRANDS = new Set(["heic", "heix", "hevc", "hevx", "heim", "heis", "mif1", "msf1"]);
/** True when the file's leading bytes identify it as HEIC/HEIF (NOT AVIF).
 *  Reads only the first 16 bytes; never trusts the extension or MIME type
 *  (iOS reports HEIC as image/heic, but files renamed .jpg still sniff true). */
export async function isHeicFile(file) {
    const buf = await file.slice(0, 16).arrayBuffer();
    const b = new Uint8Array(buf);
    // bytes 4-7 = "ftyp", bytes 8-11 = brand
    if (b.length < 12)
        return false;
    if (b[4] !== 0x66 || b[5] !== 0x74 || b[6] !== 0x79 || b[7] !== 0x70)
        return false;
    return HEIC_BRANDS.has(String.fromCharCode(b[8], b[9], b[10], b[11]));
}
/**
 * Normalize a HEIC/HEIF file to a standard raster File. Non-HEIC input is
 * returned unchanged after a cheap magic-byte check (no decode, no WASM).
 *
 * @param target output MIME — "image/jpeg" (default, small) or "image/png"
 *   (lossless, for pipelines whose own output is lossless).
 */
export async function normalizeHeicFile(file, target = "image/jpeg") {
    if (!(await isHeicFile(file)))
        return file;
    const quality = target === "image/png" ? undefined : JPEG_QUALITY;
    const stem = file.name.replace(/\.(heic|heif)$/i, "") || "image";
    const outName = `${stem}.${target === "image/png" ? "png" : "jpg"}`;
    // Safari 17+ decodes HEIC through the OS codec — skip the WASM entirely
    // (the common case for an iOS audience).
    const native = await tryNativeDecode(file, target, quality);
    if (native)
        return new File([native], outName, { type: target });
    // Chrome / Firefox / Edge: no native HEIC. Lazy-load the WASM decoder.
    // The /csp build is used because heic-to's main entry relies on
    // eval()/new Function (which needs 'unsafe-eval' in a Content-Security-
    // Policy). The eval-free /csp variant works with AND without a CSP —
    // 'wasm-unsafe-eval' is enough.
    try {
        const { heicTo } = await import("heic-to/csp");
        const blob = await heicTo({ blob: file, type: target, quality });
        return new File([blob], outName, { type: target });
    }
    catch (err) {
        throw new HeicDecodeError("decode_failed", err);
    }
}
/**
 * Decode via the browser's native codec (createImageBitmap) and re-encode on a
 * canvas. Returns null when the browser can't decode HEIC natively — Chrome and
 * Firefox reject the promise, which routes the caller to the WASM path.
 * Orientation: the OS decoder applies the HEIF `irot` transform, so the bitmap
 * is already upright; we deliberately do NOT pass imageOrientation (that would
 * re-apply any EXIF Orientation tag and double-rotate portrait shots).
 */
async function tryNativeDecode(file, target, quality) {
    if (typeof createImageBitmap !== "function")
        return null;
    let bitmap;
    try {
        bitmap = await createImageBitmap(file);
    }
    catch {
        return null; // no native HEIC decode (non-Safari) → WASM path
    }
    try {
        if (typeof OffscreenCanvas === "function") {
            const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
            const ctx = canvas.getContext("2d");
            if (!ctx)
                return null;
            ctx.drawImage(bitmap, 0, 0);
            return await canvas.convertToBlob({ type: target, quality });
        }
        const canvas = document.createElement("canvas");
        canvas.width = bitmap.width;
        canvas.height = bitmap.height;
        const ctx = canvas.getContext("2d");
        if (!ctx)
            return null;
        ctx.drawImage(bitmap, 0, 0);
        return await new Promise((resolve) => canvas.toBlob((b) => resolve(b), target, quality));
    }
    finally {
        bitmap.close();
    }
}
